    class Program
    {
        const int RequestPerSecond = 50;

        static void Main(string[] args)
        {
            WebClientTest();
        }

        static Dictionary<int, object> startTime = new Dictionary<int, object>();

        static Dictionary<int, object> execTime = new Dictionary<int, object>();

        static Dictionary<int, int> count = new Dictionary<int, int>();

        static void WebClientTest()
        {
            //while (true)
            //{
                Console.Clear();

                Console.WriteLine("Start " + RequestPerSecond + " concurrent requests...");

                ClientRequest();

                while (completedCount < RequestPerSecond)
                {
                    Thread.Sleep(1);
                }

                var max = 0;
                foreach (object value in execTime.Values)
                {
                    if (!(value is DateTime))
                    {
                        max = Math.Max(max, (int)value);
                    }
                }

                Console.WriteLine("Max response time is " + max + " miliseconds.");

                foreach (int l in count.Values)
                {
                    if (l > 100)
                    {
                        Console.WriteLine("Test failed: " + l);
                        break;
                    }
                }
                

                lock (startTime)
                {
                    startTime.Clear();

                    lock (execTime)
                    {
                        execTime.Clear();
                    }
                }

                var restartTime = 65;
                Console.WriteLine("Auto restart after {0} seconds.", restartTime);

                Thread.Sleep(restartTime * 1000);
            //}
        }

        static void ClientRequest() 
        {
            completedCount = 0;
            Random ran = new Random();
            for (var i = 1; i <= RequestPerSecond; i++)
            {
                lock (startTime)
                {
                    startTime.Add(i, (object)DateTime.Now);
                }

                WebClient client = new WebClient();
                client.DownloadDataCompleted += new DownloadDataCompletedEventHandler(client_DownloadDataCompleted);

                // Test web-farm (2 pool host 1 url)

                if (ran.Next(0, 10) % 2 == 0)
                {
                    client.DownloadDataAsync(new Uri("http://localhost:8869/Home/TestFilter?i=" + i));
                }
                else
                {
                    client.DownloadDataAsync(new Uri("http://localhost:51025/Home/TestFilter?i=" + i));
                }
            }
        }

        static int completedCount = 0;

        static void client_DownloadDataCompleted(object sender, DownloadDataCompletedEventArgs e)
        {
            completedCount++;

            ShowBlockMessage(sender as WebClient);

            int index = GetRequestIndex(sender as WebClient);
            if (index != -1)
            {
                lock (startTime)
                {
                    if (startTime.ContainsKey(index))
                    {
                        DateTime start = (DateTime)(startTime[index]);
                        DateTime end = DateTime.Now;

                        lock (execTime)
                        {
                            if (!execTime.ContainsKey(index))
                            {
                                execTime.Add(index, (end - start).Milliseconds);
                            }
                        }
                    }
                }
            }
        }

        private static void ShowBlockMessage(WebClient client)
        {
            FieldInfo responseField = client.GetType().GetField("m_WebResponse", BindingFlags.Instance | BindingFlags.NonPublic);

            if (responseField != null)
            {
                HttpWebResponse response = responseField.GetValue(client) as HttpWebResponse;

                if (response != null)
                {
                    string blocked = response.Headers["Blocked"];

                    Console.WriteLine("Blocked: {0}", blocked);
                }
            }
        }

        private static int GetRequestIndex(WebClient client)
        {
            FieldInfo requestField = client.GetType().GetField("m_WebRequest", BindingFlags.Instance | BindingFlags.NonPublic);

            if (requestField != null)
            {
                HttpWebRequest request = requestField.GetValue(client) as HttpWebRequest;
                string i = request.RequestUri.AbsoluteUri.Split(new string[] { "?i=" }, StringSplitOptions.RemoveEmptyEntries)[1];
                return int.Parse(i);
            }

            return -1;
        }

        private static int GetStatusCode(WebClient client, out string statusDescription)
        {
            FieldInfo responseField = client.GetType().GetField("m_WebResponse", BindingFlags.Instance | BindingFlags.NonPublic);

            if (responseField != null)
            {
                HttpWebResponse response = responseField.GetValue(client) as HttpWebResponse;

                if (response != null)
                {
                    completedCount++;
                    statusDescription = response.StatusDescription;
                    return (int)response.StatusCode;
                }
            }

            statusDescription = null;
            return 0;
        }
